import{_ as r}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as t,o as e,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const w=JSON.parse('{"title":"Kimi 对话与 Agent Cookbook","description":"已经打得开 kimi.com。每个配方一个任务：目标、官方入口、步骤、坑。","frontmatter":{"title":"Kimi 对话与 Agent Cookbook","description":"已经打得开 kimi.com。每个配方一个任务：目标、官方入口、步骤、坑。","domain":"product","tags":["chat"],"role":"cookbook"},"headers":[],"relativePath":"zh/products/kimi/kimi-cookbook.md","filePath":"zh/products/kimi/kimi-cookbook.md","lastUpdated":1787110548000}'),i={name:"zh/products/kimi/kimi-cookbook.md"};function l(n,o,s,g,p,h){return e(),t("div",null,[...o[0]||(o[0]=[a('<h1 id="kimi-对话与-agent-cookbook" tabindex="-1">Kimi 对话与 Agent Cookbook <a class="header-anchor" href="#kimi-对话与-agent-cookbook" aria-label="Permalink to &quot;Kimi 对话与 Agent Cookbook&quot;">​</a></h1><p>已经打得开 <a href="https://www.kimi.com/" target="_blank" rel="noreferrer">kimi.com</a>。每个配方一个任务。安装 Kimi Code 不在这里——见 <a href="/zh/products/kimi-code/">Kimi Code</a>。</p><h2 id="_1-用-agent-交出可下载产物" tabindex="-1">1. 用 Agent 交出可下载产物 <a class="header-anchor" href="#_1-用-agent-交出可下载产物" aria-label="Permalink to &quot;1. 用 Agent 交出可下载产物&quot;">​</a></h2><p><strong>目标：</strong> 要网站、PPT、表格或报告，而不是一段聊天回复。</p><p><strong>入口：</strong> <a href="https://www.kimi.com/agent" target="_blank" rel="noreferrer">kimi.com/agent</a>；App 模型切换选 <strong>K3</strong>（<a href="https://www.kimi.com/zh-cn/help/agent/agent-overview" target="_blank" rel="noreferrer">Agent 概览</a>）。</p><ol><li>用官方那种任务句：「帮我创建一个在线投票工具的网站代码」。</li><li>等它走完规划 / 工具 / 交付。</li><li>下载代码项目、Office 文件，或打开部署链接。</li></ol><p><strong>坑：</strong> 这是浏览器里的 Agent，不会改你磁盘上的 git 仓库。</p><h2 id="_2-用-swarm-做大规模搜集" tabindex="-1">2. 用 Swarm 做大规模搜集 <a class="header-anchor" href="#_2-用-swarm-做大规模搜集" aria-label="Permalink to &quot;2. 用 Swarm 做大规模搜集&quot;">​</a></h2><p><strong>目标：</strong> 上百个来源、多视角评审、超长文，单 Agent 太慢。</p><p><strong>入口：</strong> <a href="https://www.kimi.com/agent-swarm" target="_blank" rel="noreferrer">kimi.com/agent-swarm</a>；App 选 <strong>K3 Swarm</strong>（<a href="https://www.kimi.com/zh-hans/help/agent/agent-swarm" target="_blank" rel="noreferrer">Agent Swarm</a>）。</p><p>官方例子可直接改：</p><ul><li>「收集 200+ 篇 Paul Graham 文章」</li><li>「100 个 YouTube 细分领域中的 Top 3 创作者」</li><li>「基于 40 份 PDF 生成 100 页文献综述」</li></ul><p><strong>坑：</strong> 仅 Moderato 及以上；比标准 Agent 更吃额度；带 [Beta] 时可能不是全量开放。</p><h2 id="_3-给长期工作建-project" tabindex="-1">3. 给长期工作建 Project <a class="header-anchor" href="#_3-给长期工作建-project" aria-label="Permalink to &quot;3. 给长期工作建 Project&quot;">​</a></h2><p><strong>目标：</strong> 同一规范 / 同一批 PDF 要用很多轮。</p><p><strong>入口：</strong> 侧栏 Projects 旁 <strong>+</strong>，或首页 <strong>+ New project</strong>（<a href="https://www.kimi.com/help/features/project" target="_blank" rel="noreferrer">Projects</a>）。</p><ol><li>名称 1–50 字符，可选项目指令（官方例子：&quot;You are a senior product manager. Reply in Chinese and output in Markdown.&quot;）。</li><li>上传参考文件：单文件 ≤ 100 MB，最多 50 个。</li><li>每个独立产出开一条项目内对话，不要全塞进一条线程。</li><li>项目内可用 plugins、Skills、Goal，可换模型。</li></ol><p><strong>坑：</strong> 删除不可恢复。Kimi Work 的 Projects <strong>不共享</strong>这份数据。</p><h2 id="_4-定一个每天跑的任务" tabindex="-1">4. 定一个每天跑的任务 <a class="header-anchor" href="#_4-定一个每天跑的任务" aria-label="Permalink to &quot;4. 定一个每天跑的任务&quot;">​</a></h2><p><strong>目标：</strong> 日报 / 行业监测，不用每天手点。</p><p><strong>入口：</strong> 侧栏 <strong>Create scheduled task</strong>，或对话里用自然语言（<a href="https://www.kimi.com/help/features/scheduled-tasks" target="_blank" rel="noreferrer">Scheduled Tasks</a>）。</p><p>官方可复制提示：</p><blockquote><p>Every day at 9:00, summarize the latest market news as 3 key points plus 1 risk note, in Chinese, within 200 words.</p></blockquote><ol><li>先在普通对话跑通，或用「Run once now」。</li><li>若依赖 Skill：先安装并试跑，再挂到定时任务。</li><li>kimi.com 上创建的任务在云端跑，不必开着电脑。</li></ol><p><strong>坑：</strong> 默认过期：Daily +7 天，Weekly +1 月，Monthly +3 月。Kimi Work <strong>本地</strong>任务关机不补跑。到上限时新任务会存成 inactive。</p><h2 id="_5-用-skill-固定输出格式" tabindex="-1">5. 用 Skill 固定输出格式 <a class="header-anchor" href="#_5-用-skill-固定输出格式" aria-label="Permalink to &quot;5. 用 Skill 固定输出格式&quot;">​</a></h2><p><strong>目标：</strong> 周报 / SOP / 深度研究格式不要每轮重讲。</p><p><strong>入口：</strong> <a href="https://www.kimi.com/help/features/what-are-skills" target="_blank" rel="noreferrer">What are Skills?</a></p><ol><li>Skills 面板浏览官方 / 推荐技能，点 <strong>+</strong> 安装。</li><li>输入框键入 <code>/</code> 选用，或让 Kimi 按问题自动触发。</li><li>没有合适的：上传文档生成，或 <code>/skill-creator</code>。</li></ol><p>官方技能名可抄：<code>docx</code>、<code>deep-research</code>；推荐 <code>sop-writer</code>、<code>event-etf-study</code>。</p><p><strong>坑：</strong> Skill 只在相关任务加载。创建技能会耗额度（见帮助中心 Creating skills FAQ）。</p><h2 id="_6-给-agent-接插件" tabindex="-1">6. 给 Agent 接插件 <a class="header-anchor" href="#_6-给-agent-接插件" aria-label="Permalink to &quot;6. 给 Agent 接插件&quot;">​</a></h2><p><strong>目标：</strong> 查工商 / GitHub / Notion，而不是只靠网页搜索。</p><p><strong>入口：</strong> 侧栏 <strong>Plugins</strong>，或输入框 <strong>+</strong> / <code>/</code>（<a href="https://www.kimi.com/help/features/plugins" target="_blank" rel="noreferrer">Plugins</a>）。</p><ol><li>先把模型切到 <strong>K3</strong> 或 <strong>K3 Swarm</strong>（Deep Research / Websites / PPT 场景也可以）。</li><li>登录后安装；要 OAuth 的走第三方授权。</li><li>一次可以 <code>/</code> 调多个插件。</li></ol><p><strong>坑：</strong> Claw 和 Kimi Plus 对话<strong>还不能</strong>用插件。未登录不能装。列表随地区（国内 / 海外）和是否企业账号变化。有的插件按调用扣会员额度。</p><h2 id="_7-一键部署一只-claw" tabindex="-1">7. 一键部署一只 Claw <a class="header-anchor" href="#_7-一键部署一只-claw" aria-label="Permalink to &quot;7. 一键部署一只 Claw&quot;">​</a></h2><p><strong>目标：</strong> 24/7 云端助手，接到飞书 / 企微，不自己买服务器。</p><p><strong>入口：</strong> <a href="https://www.kimi.com/bot" target="_blank" rel="noreferrer">kimi.com/bot</a>（<a href="https://www.kimi.com/en/help/kimi-claw/overview" target="_blank" rel="noreferrer">Claw overview</a>）。</p><ol><li>确认会员是 <strong>Allegretto 或更高</strong>。</li><li><strong>Create</strong> Kimi Claw，等自动配置。</li><li><strong>Settings → Chat channels</strong> 配渠道。</li></ol><p>已有自建 OpenClaw：选 <strong>Link existing OpenClaw</strong>，在那台机器装 Kimi 插件。</p><p><strong>坑：</strong> 默认模型是 <strong>K2.6</strong>，走会员额度。切 K3 要改 OpenClaw 配置文件，不是网页斜杠命令。</p><h2 id="_8-开一个-claw-群聊" tabindex="-1">8. 开一个 Claw 群聊 <a class="header-anchor" href="#_8-开一个-claw-群聊" aria-label="Permalink to &quot;8. 开一个 Claw 群聊&quot;">​</a></h2><p><strong>目标：</strong> 多只 Claw 分工，Kimi Conductor 拆任务。</p><p><strong>入口：</strong> Claw 侧栏 <strong>+</strong> → <strong>Start Group Chat</strong>（<a href="https://www.kimi.com/help/kimi-claw/group-chat" target="_blank" rel="noreferrer">group-chat</a>）。</p><ol><li>填 <strong>Group Name</strong> 和 <strong>Group Goal</strong>（都必填）。</li><li>勾选已连接的 Claw，Create。</li><li>用自然语言设群规则（输出格式、语言、谁干什么）。</li><li>文件在 <strong>Workspace</strong> 预览下载。</li><li>某只 Claw 说个没完：主聊天发 <strong><code>/stop</code></strong>。</li></ol><p><strong>坑：</strong> 会员表 Claw 群聊从 Allegretto 起，10 个群。加不进去先查私聊是否在线。第三方 OpenClaw 版本以群聊帮助页为准（该页写过版本上下限）。</p><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./">学习地图</a></li><li><a href="./kimi.html">教程</a></li><li><a href="./kimi-cheatsheet.html">速查表</a></li><li><a href="./kimi-glossary.html">术语表</a></li></ul>',49)])])}const u=r(i,[["render",l]]);export{w as __pageData,u as default};
